// frameKinds is the type/subtype of every frame of a stream, in order.
func frameKinds(frames []map[string]any) (out []string) {
	for _, f := range frames {
		typ, _ := f["type"].(string)
		sub, _ := f["subtype"].(string)
		out = append(out, strings.TrimSuffix(typ+"/"+sub, "/"))
	}
	return out
}

// withoutKinds splits a sequence of frame kinds into those not in omitted and
// the omitted ones, so what is left out is named by the caller, not dropped.
func withoutKinds(kinds []string, omitted ...string) (kept, left []string) {
	for _, k := range kinds {
		drop := false
		for _, o := range omitted {
			drop = drop || k == o
		}
		if drop {
			left = append(left, k)
		} else {
			kept = append(kept, k)
		}
	}
	return kept, left
}

// TestTheStreamOfARecordedRunHasThinkingFramesTheMockDoesNotEmit: recorded
// (runs/pretool-refusal and runs/noninteractive-no-force), the print-mode
// stream is system init, the user's prompt, then, as the agent works, thinking
// frames (one or more "delta" frames carrying a piece of the model's own
// reasoning text, closed by a "completed" frame; both carry the session id and
// a timestamp), the assistant's text, the tool calls, and a closing result.
// The thinking text and the assistant's words are the model's own; the mock
// calls no model, so its replay of the same run streams system init, the
// prompt, the same tool-call frames and the result, with no thinking frame and
// no assistant text (declared as a modeled-surface deviation). Every other
// frame of the recorded sequence is in the replay, in order.
